/* Appearance → Theme Options (generated by DEVOUR). */
(function ($) {
	'use strict';

	var cfg = window.wpmThemeOptions || {};
	var $form = $('#wpm-options-form');
	var frame = document.getElementById('wpm-preview-frame');
	var $status = $('.wpm-status');
	if (!$form.length) {
		return;
	}

	/* ---------------------------------------------------------------- tabs */
	var TAB_KEY = 'wpmThemeOptionsTab';

	function showTab(tab) {
		if (!$('.wpm-panel[data-panel="' + tab + '"]').length) {
			tab = $('.wpm-tabs .nav-tab').first().data('tab');
		}
		$('.wpm-tabs .nav-tab').each(function () {
			$(this).toggleClass('nav-tab-active', $(this).data('tab') === tab);
		});
		$('.wpm-panel').each(function () {
			$(this).prop('hidden', $(this).data('panel') !== tab);
		});
		try { sessionStorage.setItem(TAB_KEY, tab); } catch (e) { /* storage unavailable */ }
	}

	$('.wpm-tabs').on('click', '.nav-tab', function (e) {
		e.preventDefault();
		showTab($(this).data('tab'));
		history.replaceState(null, '', '#' + $(this).data('tab'));
	});

	var initial = (location.hash || '').replace('#', '');
	if (!initial) {
		try { initial = sessionStorage.getItem(TAB_KEY) || ''; } catch (e) { initial = ''; }
	}
	showTab(initial);

	/* ------------------------------------------------------- live preview */
	var timer = null;
	var request = null;

	function refreshPreview() {
		if (!frame) {
			return;
		}
		var data = new FormData($form[0]);
		data.delete(cfg.option + '[_import]');
		data.append('action', 'wpm_theme_preview');
		data.append('nonce', cfg.nonce);

		if (request) {
			request.abort();
		}
		request = new AbortController();
		$status.text('Updating preview…');

		fetch(cfg.ajaxUrl, { method: 'POST', body: data, credentials: 'same-origin', signal: request.signal })
			.then(function (r) { return r.json(); })
			.then(function (res) {
				if (!res || !res.success) {
					throw new Error('Preview failed');
				}
				var scroll = 0;
				try { scroll = frame.contentWindow.scrollY; } catch (e) { /* cross-origin */ }
				frame.onload = function () {
					try { frame.contentWindow.scrollTo(0, scroll); } catch (e) { /* ignore */ }
					$status.text('Preview updated — not saved yet');
				};
				frame.src = res.data.url + '&t=' + Date.now();
			})
			.catch(function (err) {
				if (err.name !== 'AbortError') {
					$status.text('Could not update the preview');
				}
			});
	}

	function schedule() {
		clearTimeout(timer);
		timer = setTimeout(refreshPreview, 500);
	}

	$form.on('input change', 'input, select, textarea', function () {
		if (this.name && this.name.indexOf('[_import]') !== -1) {
			return;
		}
		schedule();
	});

	/* ------------------------------------------------------ color pickers */
	$('.wpm-color').wpColorPicker({
		change: function () { setTimeout(schedule, 0); },
		clear: function () { setTimeout(schedule, 0); }
	});

	/* -------------------------------------------------------- logo picker */
	$form.on('click', '.wpm-media-select', function (e) {
		e.preventDefault();
		var $field = $(this).closest('.wpm-field');
		var picker = wp.media({ title: 'Choose logo', button: { text: 'Use as logo' }, library: { type: 'image' }, multiple: false });
		picker.on('select', function () {
			var image = picker.state().get('selection').first().toJSON();
			var url = (image.sizes && image.sizes.medium) ? image.sizes.medium.url : image.url;
			$field.find('.wpm-media-id').val(image.id).trigger('change');
			$field.find('.wpm-media-preview').attr('src', url).prop('hidden', false);
			$field.find('.wpm-media-remove').prop('hidden', false);
			$field.find('.wpm-media-select').text('Replace logo');
		});
		picker.open();
	});

	$form.on('click', '.wpm-media-remove', function (e) {
		e.preventDefault();
		var $field = $(this).closest('.wpm-field');
		$field.find('.wpm-media-id').val('0').trigger('change');
		$field.find('.wpm-media-preview').attr('src', '').prop('hidden', true);
		$(this).prop('hidden', true);
		$field.find('.wpm-media-select').text('Choose logo');
	});

	/* -------------------------------------------------------------- menus */
	function ajax(action, extra) {
		var data = new FormData();
		data.append('action', action);
		data.append('nonce', cfg.nonce);
		Object.keys(extra || {}).forEach(function (k) { data.append(k, extra[k]); });
		return fetch(cfg.ajaxUrl, { method: 'POST', body: data, credentials: 'same-origin' })
			.then(function (r) { return r.json(); });
	}

	// Show "Edit menu items" for the selected menu.
	function syncEditLink($select) {
		var url = $select.find('option:selected').data('edit') || '';
		$select.closest('.wpm-field').find('.wpm-menu-edit').attr('href', url || '#').prop('hidden', !url);
	}

	// Rebuild every menu dropdown from fresh choices, keeping each selection.
	function renderMenuChoices(choices) {
		$('.wpm-nav-select').each(function () {
			var $select = $(this);
			var current = $select.val();
			$select.find('optgroup').remove();
			[['classic', 'Menus'], ['block', 'Site Editor menus']].forEach(function (group) {
				var items = choices[group[0]] || [];
				if (!items.length) {
					return;
				}
				var $group = $('<optgroup>').attr('label', group[1]).attr('data-group', group[0]);
				items.forEach(function (menu) {
					$('<option>').val(menu.value).text(menu.label).attr('data-edit', menu.edit).appendTo($group);
				});
				$select.append($group);
			});
			$select.val($select.find('option[value="' + current + '"]').length ? current : '0');
			syncEditLink($select);
		});
	}

	$('.wpm-nav-select').each(function () { syncEditLink($(this)); });
	$form.on('change', '.wpm-nav-select', function () { syncEditLink($(this)); });

	$form.on('click', '.wpm-menu-create', function () {
		var $button = $(this);
		var $select = $button.closest('.wpm-field').find('.wpm-nav-select');
		var name = window.prompt('Name for the new menu:', $button.data('name') || 'Main menu');
		if (!name || !name.trim()) {
			return;
		}
		$button.prop('disabled', true);
		$status.text('Creating menu…');
		ajax('wpm_create_menu', { name: name.trim() })
			.then(function (res) {
				if (!res || !res.success) {
					throw new Error(res && res.data && res.data.message ? res.data.message : 'Could not create the menu');
				}
				renderMenuChoices(res.data.choices);
				$select.val(res.data.value).trigger('change');
				$status.text('Menu “' + res.data.label + '” created with Home + your pages and selected. Use “Edit menu items” to change it, then Save.');
			})
			.catch(function (err) {
				$status.text('');
				window.alert(err.message);
			})
			.finally(function () { $button.prop('disabled', false); });
	});

	// Menus are edited in another tab: refresh the lists (and preview) when we get focus back.
	var lastRefresh = Date.now();
	window.addEventListener('focus', function () {
		if (Date.now() - lastRefresh < 3000) {
			return;
		}
		lastRefresh = Date.now();
		ajax('wpm_list_menus').then(function (res) {
			if (res && res.success) {
				renderMenuChoices(res.data);
				schedule();
			}
		});
	});

	/* ------------------------------------------------------------ devices */
	$('.wpm-devices').on('click', 'button', function () {
		$('.wpm-devices button').removeClass('is-active');
		$(this).addClass('is-active');
		$('.wpm-preview__frame').attr('data-device', $(this).data('device'));
	});

	/* Leaving with unsaved changes? */
	var dirty = false;
	$form.on('change input', function () { dirty = true; });
	$form.on('submit', function () { dirty = false; });
	window.addEventListener('beforeunload', function (e) {
		if (dirty) {
			e.preventDefault();
			e.returnValue = '';
		}
	});
})(jQuery);
